 ("debrief.stat.dose","Radiation dose: {0} mSv (limit {1})","ปริมาณรังสี: {0} mSv (ขีดจำกัด {1})"),
 ("debrief.stat.science","Science tasks: {0}/{1}","งานวิทยาศาสตร์: {0}/{1}"),
 ("debrief.stat.cards","Cards found on this world: {0}/{1}","การ์ดที่พบบนดาวนี้: {0}/{1}"),
 ("debrief.lessons","What to remember next time","สิ่งที่ควรจำไว้ครั้งหน้า"),
 ("debrief.night","Night {0}","คืนที่ {0}"),
